package com.auca.student;
import com.auca.abstracts.AcademicMember; import com.auca.department.Department; import com.auca.exceptions.ValidationException; import java.time.LocalDate;
public class Student extends AcademicMember {
 private String studentNumber, programName, guardianPhone; private LocalDate admissionDate; private int studyYear; private boolean scholarshipStatus;
 public Student(String personId,String firstName,String lastName,String email,String phoneNumber,LocalDate dob,String memberNumber,Department department,LocalDate joinDate,String academicStatus,String institutionalEmail,String advisorName,String studentNumber,String programName,LocalDate admissionDate,int studyYear,String guardianPhone,boolean scholarshipStatus){super(personId,firstName,lastName,email,phoneNumber,dob,memberNumber,department,joinDate,academicStatus,institutionalEmail,advisorName);this.studentNumber=studentNumber;this.programName=programName;this.admissionDate=admissionDate;this.studyYear=studyYear;this.guardianPhone=guardianPhone;this.scholarshipStatus=scholarshipStatus;}
 public String getRoleDescription(){return "Student";} public String getAcademicCategory(){return "Undergraduate student";}
 public void validate() throws ValidationException {super.validate();if(studentNumber==null||studentNumber.isBlank()||programName==null||programName.isBlank()||admissionDate==null||studyYear<1||studyYear>6||guardianPhone==null||!guardianPhone.matches("^\\+?[0-9]{10,15}$"))throw new ValidationException("Invalid student details. Study year must be 1-6 and guardian phone 10-15 digits.");if(admissionDate.isAfter(LocalDate.now()))throw new ValidationException("Admission date cannot be in the future.");}
 public String getStudentNumber(){return studentNumber;} public void setStudentNumber(String v){studentNumber=v;} public String getProgramName(){return programName;} public void setProgramName(String v){programName=v;} public LocalDate getAdmissionDate(){return admissionDate;} public void setAdmissionDate(LocalDate v){admissionDate=v;} public int getStudyYear(){return studyYear;} public void setStudyYear(int v){studyYear=v;} public String getGuardianPhone(){return guardianPhone;} public void setGuardianPhone(String v){guardianPhone=v;} public boolean isScholarshipStatus(){return scholarshipStatus;} public void setScholarshipStatus(boolean v){scholarshipStatus=v;}
 public String getId(){return studentNumber;} public String getDisplayName(){return getFirstName()+" "+getLastName()+" ("+studentNumber+")";} public String toString(){return "STUDENT\n"+super.toString()+", Student No: "+studentNumber+", Program: "+programName+", Admission: "+admissionDate+", Year: "+studyYear+", Guardian: "+guardianPhone+", Scholarship: "+scholarshipStatus;}
}
